 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();static readonly List<IntPtr> allocations=new List<IntPtr>();static IntPtr client;static string directory,verifier;static ulong application;static bool ready,stop;static int parentId;static int sdkStatus;static FreeCb freeCb=p=>{};static StatusCb statusCb=Status;static AuthCb authCb=Authorized;static TokenCb tokenCb=Token;static ResultCb resultCb=Updated;
 static IntPtr Obj(){var p=Marshal.AllocHGlobal(256);Marshal.Copy(new byte[256],0,p,256);allocations.Add(p);return p;}
 static void Release(IntPtr p){Marshal.FreeHGlobal(p);allocations.Remove(p);}
 static Str Input(string s){var bytes=Encoding.UTF8.GetBytes(s??"");var p=Marshal.AllocHGlobal(bytes.Length+1);Marshal.Copy(bytes,0,p,bytes.Length);allocations.Add(p);return new Str{ptr=p,size=(UIntPtr)bytes.Length};}
 static string Text(Str s){int n=checked((int)s.size.ToUInt64());if(n<0||n>1000000)throw new Exception("Dimensione SDK non valida");var b=new byte[n];if(n>0)Marshal.Copy(s.ptr,b,0,n);return Encoding.UTF8.GetString(b);}
 static string Owned(Str s){var t=Text(s);if(s.ptr!=IntPtr.Zero)Discord_Free(s.ptr);return t;}
 static void Write(string status,string error="",object friends=null){var result=new Dictionary<string,object>{{"status",status},{"error",error},{"sdkStatus",sdkStatus},{"updated",DateTime.UtcNow.ToString("O")},{"friends",friends??new object[0]}};var f=Path.Combine(directory,"discord-status.json");File.WriteAllText(f+".tmp",Json.Serialize(result));if(File.Exists(f))File.Delete(f);File.Move(f+".tmp",f);}
 static bool Ok(IntPtr r){var ok=Discord_ClientResult_Successful(r);if(!ok){Str s;Discord_ClientResult_Error(r,out s);var error=Owned(s);Write("configuration_required","Discord: "+error+". Controlla Social SDK, Public Client e redirect http://127.0.0.1/callback nel portale.");}Discord_ClientResult_Drop(r);return ok;}
 static void Status(int status,int error,int detail,IntPtr ignored){sdkStatus=status;ready=status==3;if(ready)Write("ready");else if(error!=0)Write("connection_error","Discord non ha completato il collegamento ("+error+" / "+detail+").");}
 static void Authorized(IntPtr r,Str code,Str redirect,IntPtr ignored){try{if(!Ok(r)){stop=true;return;}Discord_Client_GetToken(client,application,code,Input(verifier),redirect,tokenCb,freeCb,IntPtr.Zero);}finally{Discord_Free(code.ptr);Discord_Free(redirect.ptr);}}
 static void Token(IntPtr r,Str access,Str refresh,int type,int expires,Str scopes,IntPtr ignored){try{if(!Ok(r)){stop=true;return;}var token=Text(access);var payload=Json.Serialize(new Dictionary<string,object>{{"token",token},{"type",type},{"expires",DateTime.UtcNow.AddSeconds(expires).ToString("O")},{"app",application.ToString()}});File.WriteAllBytes(Path.Combine(directory,"discord-session.bin"),ProtectedData.Protect(Encoding.UTF8.GetBytes(payload),null,DataProtectionScope.CurrentUser));Discord_Client_UpdateToken(client,type,access,resultCb,freeCb,IntPtr.Zero);}finally{Discord_Free(access.ptr);Discord_Free(refresh.ptr);Discord_Free(scopes.ptr);}}
 static void Updated(IntPtr result,IntPtr ignored){if(!Ok(result)){stop=true;return;}Write("connecting");Discord_Client_Connect(client);}
 static void Friends(){Str span;Discord_Client_GetRelationships(client,out span);var count=checked((int)span.size.ToUInt64());if(count>10000)throw new Exception("Numero amici non valido");var rows=new List<object>();int stride=8;if(count>0){var copy=Obj();var pattern=Enumerable.Repeat((byte)0xAA,256).ToArray();Marshal.Copy(pattern,0,copy,256);Discord_RelationshipHandle_Clone(copy,span.ptr);var bytes=new byte[256];Marshal.Copy(copy,bytes,0,256);var last=Array.FindLastIndex(bytes,b=>b!=0xAA);stride=((last+8)/8)*8;if(stride<8||stride>64)throw new Exception("Formato SDK non riconosciuto");Discord_RelationshipHandle_Drop(copy);Release(copy);}
  try{for(int i=0;i<count;i++){var rel=IntPtr.Add(span.ptr,i*stride);try{if(Discord_RelationshipHandle_DiscordRelationshipType(rel)!=1)continue;var user=Obj();if(!Discord_RelationshipHandle_User(rel,user)){Release(user);continue;}try{Str name;Discord_UserHandle_DisplayName(user,out name);Str avatar;Discord_UserHandle_AvatarUrl(user,2,2,out avatar);var activity=Obj();string game="";if(Discord_UserHandle_GameActivity(user,activity)){Str title;Discord_Activity_Name(activity,out title);game=Owned(title);Discord_Activity_Drop(activity);}Release(activity);rows.Add(new Dictionary<string,object>{{"id",Discord_UserHandle_Id(user).ToString()},{"name",Owned(name)},{"avatar",Owned(avatar)},{"status",Discord_UserHandle_Status(user)},{"game",game}});}finally{Discord_UserHandle_Drop(user);Release(user);}}finally{Discord_RelationshipHandle_Drop(rel);}}}finally{Discord_Free(span.ptr);}Write("ready","",rows);}
 [STAThread]static int Main(string[] args){try{directory=Path.GetFullPath(args[0]);Directory.CreateDirectory(directory);application=ulong.Parse(args[1]);var parentArg=args.FirstOrDefault(x=>x.StartsWith("--parent:"));if(parentArg!=null)int.TryParse(parentArg.Substring(9),out parentId);using(var mutex=new Mutex(true,"Local\\NovaDiscordSocial-"+application,out var created)){if(!created)return 0;var dll=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"discord_partner_sdk.dll");if(LoadLibraryEx(dll,IntPtr.Zero,0x1100)==IntPtr.Zero)throw new Exception("Social SDK Discord non trovato sul PC.");client=Obj();Discord_Client_Init(client);Discord_Client_SetApplicationId(client,application);Str scopes;Discord_Client_GetDefaultPresenceScopes(out scopes);var scope=Owned(scopes);if(args.Contains("--probe")){Write("sdk_available",scope);Console.WriteLine("SDK disponibile: "+scope);return 0;}
 Discord_Client_SetStatusChangedCallback(client,statusCb,freeCb,IntPtr.Zero);var session=Path.Combine(directory,"discord-session.bin");if(!args.Contains("--login")&&File.Exists(session)){var data=Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(session),null,DataProtectionScope.CurrentUser)));DateTime expires;if(Convert.ToString(data["app"])!=application.ToString()||!DateTime.TryParse(Convert.ToString(data["expires"]),out expires)||expires.ToUniversalTime()<DateTime.UtcNow){Write("login_required","Ricollega Discord per aggiornare l’accesso.");return 0;}Discord_Client_UpdateToken(client,Convert.ToInt32(data["type"]),Input(Convert.ToString(data["token"])),resultCb,freeCb,IntPtr.Zero);}else if(args.Contains("--login")){Write("authorizing","Conferma il collegamento nella finestra Discord.");var v=Obj();Discord_Client_CreateAuthorizationCodeVerifier(client,v);Str value;Discord_AuthorizationCodeVerifier_Verifier(v,out value);verifier=Owned(value);var challenge=Obj();Discord_AuthorizationCodeVerifier_Challenge(v,challenge);var auth=Obj();Discord_AuthorizationArgs_Init(auth);Discord_AuthorizationArgs_SetClientId(auth,application);Discord_AuthorizationArgs_SetScopes(auth,Input(scope));Discord_AuthorizationArgs_SetCodeChallenge(auth,challenge);Discord_Client_Authorize(client,auth,authCb,freeCb,IntPtr.Zero);}else{Write("login_required","Collega il tuo account Discord.");return 0;}
 var next=DateTime.UtcNow;var started=DateTime.UtcNow;while(!stop){if(parentId>0){try{if(System.Diagnostics.Process.GetProcessById(parentId).HasExited)break;}catch{break;}}Discord_RunCallbacks();if(ready&&DateTime.UtcNow>=next){Friends();next=DateTime.UtcNow.AddSeconds(5);}if(!ready&&DateTime.UtcNow-started>TimeSpan.FromMinutes(3)){Write("login_required","Collegamento non completato. Controlla la configurazione dell’app Discord e riprova.");break;}if(File.Exists(Path.Combine(directory,"discord-stop.flag"))){File.Delete(Path.Combine(directory,"discord-stop.flag"));break;}Thread.Sleep(25);}}return 0;}catch(Exception e){if(directory!=null)Write("error",e.Message);return 1;}}
